try {
  const mensaje = $input.first().json;
  if (!mensaje || typeof mensaje !== 'object') throw new Error('Mensaje de Telegram inválido');
  if (!mensaje.message) throw new Error('Campo message no encontrado');

  const chat_id = mensaje.message?.chat?.id;
  if (!chat_id) throw new Error('Chat ID no encontrado');

  const nombre = ((mensaje.message?.from?.first_name || '') + ' ' + (mensaje.message?.from?.last_name || '')).trim();
  if (!nombre || nombre.length < 2) throw new Error('Nombre vacío');

  const mensaje_texto = mensaje.message?.text || '';
  if (!mensaje_texto) throw new Error('Mensaje vacío');
  if (mensaje_texto.length > 5000) throw new Error('Mensaje muy largo');

  const username = mensaje.message?.from?.username || '';

  return { 
    json: { 
      chat_id: chat_id.toString(), 
      nombre_telegram: nombre, 
      username, 
      mensaje_texto, 
      timestamp: new Date().toISOString(), 
      error: false 
    } 
  };
} catch (error) {
  return { 
    json: { 
      error: true, 
      error_tipo: 'IDENTIFICACION_FALLIDA', 
      error_mensaje: error.message, 
      chat_id: $input.first().json?.message?.chat?.id?.toString() || 'DESCONOCIDO' 
    } 
  };
}

// GENERAR ID DE PROYECTO
const timestamp = Date.now().toString().slice(-8);
const proyectoId = `PROJ-${timestamp}`;
const datos = $input.first().json;

return { 
  json: {
    proyecto_id: proyectoId,
    nombre: `Proyecto ${datos.nombre_telegram}`,
    tipo: 'Consultoría General',
    estado: 'Nuevo',
    fecha_inicio: new Date().toISOString().split('T')[0],
    fecha_limite: '',
    prioridad: '🟡 Media',
    progreso: '0%',
    tiempo_estimado: '0h',
    tiempo_real: '0h',
    notas: datos.mensaje_texto || '',
    responsable: 'Manuela',
    chat_id: datos.chat_id,
    nombre_telegram: datos.nombre_telegram
  }
};

// DESGLOSADOR DE PROYECTOS CON PRIORIZACIÓN
const proyecto = $input.first().json;
const servicio = proyecto.tipo || 'Consultoría General';
const descripcion = proyecto.mensaje_texto || proyecto.notas || '';

// PLANTILLAS DE TAREAS
const plantillas = {
  'Consultoría CRM': [
    { descripcion: '🔍 Análisis necesidades y procesos', tiempo: '2h', prioridad: '🔴 Alta', categoria: 'Análisis' },
    { descripcion: '🛠️ Configuración inicial CRM', tiempo: '4h', prioridad: '🔴 Alta', categoria: 'Implementación' },
    { descripcion: '📊 Migración de datos', tiempo: '3h', prioridad: '🟡 Media', categoria: 'Datos' },
    { descripcion: '👥 Capacitación del equipo', tiempo: '2h', prioridad: '🟢 Baja', categoria: 'Formación' },
    { descripcion: '✅ Revisión y ajustes finales', tiempo: '1h', prioridad: '🟡 Media', categoria: 'Calidad' }
  ],
  'Consultoría General': [
    { descripcion: '🔍 Reunión inicial y análisis', tiempo: '1h', prioridad: '🔴 Alta', categoria: 'Análisis' },
    { descripcion: '📋 Planificación del proyecto', tiempo: '2h', prioridad: '🔴 Alta', categoria: 'Planificación' },
    { descripcion: '🛠️ Implementación de solución', tiempo: '4h', prioridad: '🟡 Media', categoria: 'Implementación' },
    { descripcion: '🧪 Pruebas y ajustes', tiempo: '2h', prioridad: '🟡 Media', categoria: 'Testing' },
    { descripcion: '📞 Seguimiento post-implementación', tiempo: '1h', prioridad: '🟢 Baja', categoria: 'Soporte' }
  ]
};

// DETECTAR TIPO
let tipoDetectado = 'Consultoría General';
const mensajeLower = descripcion.toLowerCase();
if (mensajeLower.includes('crm') || mensajeLower.includes('cliente')) {
  tipoDetectado = 'Consultoría CRM';
}

// GENERAR TAREAS CON SCORING
const ahora = new Date();
const tareasBase = plantillas[tipoDetectado] || plantillas['Consultoría General'];

const tareasConScore = tareasBase.map((t, i) => {
  let urgencia = 1, importancia = 1, impacto = 1;

  if (/configur|implementar/i.test(t.descripcion)) impacto += 2;
  if (/análisis|planificación/i.test(t.descripcion)) importancia += 2;

  if (t.prioridad === '🔴 Alta') { urgencia += 3; importancia += 2; }
  if (t.prioridad === '🟡 Media') { urgencia += 2; }
  if (t.prioridad === '🟢 Baja') { importancia += 1; }

  const puntuacion = urgencia*0.45 + importancia*0.35 + impacto*0.2;

  return { 
    ...t, 
    urgencia, 
    importancia, 
    impacto, 
    puntuacion: Math.round(puntuacion*10)/10,
    tarea_id: `TASK-${Date.now().toString().slice(-6)}-${i+1}`
  };
});

// ORDENAR POR PUNTUACIÓN
const tareasPriorizadas = tareasConScore.sort((a,b) => b.puntuacion - a.puntuacion);

// CALCULAR TIEMPO TOTAL
const tiempoTotal = tareasPriorizadas.reduce((total, t) => {
  const horas = parseInt(t.tiempo) || 0;
  return total + horas;
}, 0);

// CALCULAR FECHA ENTREGA
const diasEntrega = Math.max(3, Math.ceil(tiempoTotal / 8));
const fechaEntrega = new Date();
fechaEntrega.setDate(fechaEntrega.getDate() + diasEntrega);

return {
  json: {
    ...proyecto,
    servicio_detectado: tipoDetectado,
    tareas_generadas: tareasPriorizadas,
    tareas_totales: tareasPriorizadas.length,
    tiempo_total_estimado: `${tiempoTotal}h`,
    fecha_entrega_estimada: fechaEntrega.toISOString().split('T')[0],
    dias_estimados: diasEntrega
  }
};

// CALCULADOR DE TIEMPO Y EFICIENCIA
const proyecto = $input.first().json;
const tareasGeneradas = proyecto.tareas_generadas || [];

// MÉTRICAS
const tareasTotales = tareasGeneradas.length;
const tareasCompletadas = 0; // Inicialmente ninguna completada
const tareasPendientes = tareasTotales;

// CALCULAR TIEMPOS
const tiempoEstimadoTotal = tareasGeneradas.reduce((total, t) => {
  const match = t.tiempo?.match(/(\d+)h/) || [0, 0];
  return total + parseInt(match[1]);
}, 0);

const tiempoRealTotal = 0; // Inicialmente 0
const tiempoPendiente = tiempoEstimadoTotal;

// EFICIENCIA Y ALERTAS
const eficiencia = 100;
let alertas = [];

if (tiempoPendiente > 16) {
  alertas.push('📅 Carga alta - considerar replanificación');
}

// CALCULAR CARGA DE TRABAJO
const horasPorDia = 6;
const diasRestantes = Math.ceil(tiempoPendiente / horasPorDia);

let cargaTrabajo = '🟢 Baja';
if (tiempoPendiente > 20) cargaTrabajo = '🔴 Alta';
else if (tiempoPendiente > 10) cargaTrabajo = '🟡 Media';

return {
  json: {
    ...proyecto,
    progreso_global: '0%',
    tareas_completadas: tareasCompletadas,
    tareas_pendientes: tareasPendientes,
    tiempo_estimado_total: `${tiempoEstimadoTotal}h`,
    tiempo_real_total: `${tiempoRealTotal}h`,
    tiempo_pendiente: `${tiempoPendiente}h`,
    eficiencia_global: `${eficiencia}%`,
    alertas_automaticas: alertas,
    dias_restantes: diasRestantes,
    carga_trabajo: cargaTrabajo
  }
};

// OPTIMIZADOR DE CARGA
const proyecto = $input.first().json;
const tareasGeneradas = proyecto.tareas_generadas || [];
const tareasPendientes = tareasGeneradas;

// PARÁMETROS
const horasPorDia = 6;
const diasLaborables = 5;
const horasSemanales = horasPorDia * diasLaborables;

// CALCULAR HORAS PENDIENTES
const horasPendientes = tareasPendientes.reduce((total, t) => {
  const horas = parseInt(t.tiempo) || 0;
  return total + horas;
}, 0);

// DISTRIBUCIÓN
const semanasNecesarias = Math.ceil(horasPendientes / horasSemanales);
const cargaDiaria = horasPendientes / (semanasNecesarias * diasLaborables);

// PLAN SEMANAL
const planSemanal = [];
let horasAsignadas = 0;
let diaActual = 1;

tareasPendientes.forEach(tarea => {
  const horasTarea = parseInt(tarea.tiempo) || 0;

  if (horasAsignadas + horasTarea <= horasSemanales) {
    planSemanal.push({
      tarea: tarea.descripcion,
      prioridad: tarea.prioridad,
      tiempo: tarea.tiempo,
      categoria: tarea.categoria,
      puntuacion: tarea.puntuacion,
      semana: 1,
      dia: diaActual
    });

    horasAsignadas += horasTarea;
    if (horasAsignadas >= horasPorDia) {
      diaActual++;
      horasAsignadas = 0;
    }
  }
});

// RECOMENDACIONES
let optimizaciones = [];

if (semanasNecesarias > 2) {
  optimizaciones.push('📅 Proyecto extenso - considerar dividir en fases');
}

if (cargaDiaria > 8) {
  optimizaciones.push('⚡ Carga diaria alta - evaluar delegación');
}

if (tareasPendientes[0]?.puntuacion > 4) {
  optimizaciones.push('🎯 Tareas críticas identificadas - enfocar recursos');
}

return {
  json: {
    ...proyecto,
    carga_trabajo_horas: horasPendientes,
    semanas_estimadas: semanasNecesarias,
    carga_diaria_promedio: `${cargaDiaria.toFixed(1)}h/día`,
    plan_semanal_optimizado: planSemanal,
    optimizaciones_recomendadas: optimizaciones,
    puede_autogestionarse: horasPendientes <= 40 && semanasNecesarias <= 2,
    necesita_supervision: horasPendientes > 40 || semanasNecesarias > 2
  }
};

// PROCESAR RESPUESTA DEL AGENTE
const agentResponse = $input.first().json;
const contexto = $('🔍 Identificar Cliente').first().json;

let respuestaFinal = '';
let accionDetectada = 'conversacion';
let datosAccion = {};

// EXTRAER RESPUESTA
if (agentResponse.output && typeof agentResponse.output === 'string') {
  respuestaFinal = agentResponse.output;

  // DETECTAR SI HAY COMANDOS EN LA RESPUESTA
  const textoLower = contexto.mensaje_texto.toLowerCase();

  if (textoLower.startsWith('/encargo')) {
    accionDetectada = 'crear_desglose';
    datosAccion = { descripcion: contexto.mensaje_texto.replace('/encargo', '').trim() };
  } else if (textoLower.startsWith('/completar')) {
    accionDetectada = 'completar_tarea';
    const match = contexto.mensaje_texto.match(/(TASK-\d+)\s+(\d+)%/i);
    if (match) {
      datosAccion = { tarea_id: match[1], progreso: parseInt(match[2]) };
    }
  } else if (textoLower.startsWith('/gasto')) {
    accionDetectada = 'registrar_gasto';
    const match = contexto.mensaje_texto.match(/\/gasto\s+([0-9]+(?:[.,][0-9]{1,2})?)\s+(.+?)(?:\s+#([a-z0-9_-]+))?$/i);
    if (match) {
      datosAccion = { 
        monto: parseFloat(match[1].replace(',', '.')), 
        concepto: match[2].trim(), 
        categoria: (match[3] || 'General').trim() 
      };
    }
  } else if (textoLower.startsWith('/agenda')) {
    accionDetectada = 'agenda_semana';
    let rango = 'semana';
    if (textoLower.includes('hoy')) rango = 'hoy';
    if (textoLower.includes('mañana')) rango = 'manana';
    datosAccion = { rango };
  } else if (textoLower.startsWith('/estado')) {
    accionDetectada = 'estado_tarea';
    const match = contexto.mensaje_texto.match(/(TASK-\d+)/i);
    datosAccion = { tarea_id: match ? match[1] : 'T-001' };
  } else if (textoLower.startsWith('/panel')) {
    accionDetectada = 'panel_control';
  } else if (textoLower.startsWith('/ayuda') || textoLower.startsWith('/help')) {
    accionDetectada = 'ayuda';
  }
}

return {
  json: {
    respuesta_cliente: respuestaFinal,
    chat_id: contexto.chat_id,
    accion: accionDetectada,
    datos_accion: datosAccion,
    mensaje_original: contexto.mensaje_texto,
    enviar_telegram: true
  }
};
